"""Implementation work needed for standards features the emitter cannot lower."""


def grouped(entries):
    """Catch duplicate decisions during review or when updating a standards snapshot."""
    out = {}
    for names, plan in entries:
        for name in names.split():
            if name in out:
                raise ValueError(f"duplicate mapping for {name}")
            out[name] = plan
    return out


